INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('axustes', 'xeral', '{"nome":"Feira da Sostibilidade","lema":"Pensa, consume e actúa","descricion":"A Feira da Sostibilidade do IES Luís Seoane (Pontevedra): un movemento educativo de alumnado, profesorado, universidade e entidades sociais arredor dos retos ecosociais e da cidadanía global.","edicionActual":"2027","instagram":"https://www.instagram.com/feiradasostibilidade","instagramUsuario":"@feiradasostibilidade","webIes":"https://iesluisseoane.org/","pe":{"texto":"Pensa, consume e actúa. Un movemento educativo nacido no IES Luís Seoane de Pontevedra a partir do colectivo Eco-Étika.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Co apoio de","entidades":["cooperacion-galega"],"nota":"V Feira · proxecto SENDA 2030"},{"titulo":"Colabora","entidades":["cfr-pontevedra"]}],"premios":[{"ano":"2022 · 2023","texto":"Premio Galicons-net de Innovación Educativa en Consumo Responsable (Xunta de Galicia)"},{"ano":"2024","texto":"III Premio Galego de Educación para o Desenvolvemento e a Cidadanía Global, á experiencia de Eco-Étika e o IES Luís Seoane"}]}}', 0) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2027', '{"numero":5,"ano":2027,"titulo":"V Feira da Sostibilidade · SENDA 2030","lema":"Eco-Étika en acción","datas":"28, 29 e 30 de abril de 2027","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"proxima","resumo":"O punto de encontro de SENDA 2030: un curso de investigación, diálogo entre territorios e acción protagonizada polo alumnado, que se mostra en abril no IES Luís Seoane.","portada":"f-multitude-corredor","portadaAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira da Sostibilidade","cifras":[],"fitos":["II Foro de Desenvolvemento Local","I Conferencia COOPEDUGAL","Microproxectos Eco-Étika. Pensa. Actúa.","Voces do Sur Global"],"proxecto":"senda-2030","seccions":[{"tipo":"cronoloxia","id":"spb7yv","oculta":false,"fondo":"branco","etiqueta":"SENDA 2030 · O camiño ata a Feira","titulo":"Investigar, contrastar, actuar.","fitos":[{"data":"Outono 2026","titulo":"Arranque","texto":"Coordinación cos centros participantes e liña de base.","estado":"agora"},{"data":"Novembro 2026 – marzo 2027","titulo":"Formación, laboratorio e ciencia cidadá","texto":"Formación docente en EpDCG, laboratorio de propostas educativas, obradoiros de cidadanía global e microproxectos Eco-Étika nas aulas.","estado":"proximo"},{"data":"Primavera 2027","titulo":"Diálogo entre territorios","texto":"Encontros local-global con docentes de América Latina, Eco-Étika Conecta e a campaña «Dálle a volta».","estado":"proximo"},{"data":"28–30 abril 2027","titulo":"V Feira da Sostibilidade","texto":"Tres xornadas no IES Luís Seoane co II Foro de Desenvolvemento Local e a I Conferencia COOPEDUGAL.","estado":"proximo"},{"data":"Maio – setembro 2027","titulo":"SENDA Aberta","texto":"Sistematización, documental e guía «Así fixemos SENDA» para que outros centros poidan adaptar a experiencia.","estado":"proximo"}],"ancla":"senda-2030","texto":"SENDA 2030. Xeración Eco-Étika é o proxecto de CIDEL Galicia e a Universidade de Vigo, co IES Luís Seoane, que une ciencia cidadá, práctica docente e participación xuvenil durante todo o curso. Así é o camiño:"},{"tipo":"tarxetas","id":"sqt9z1","oculta":false,"fondo":"claro","etiqueta":"Na Feira","titulo":"Que haberá na V Feira.","columnas":3,"items":[{"titulo":"Stands e microproxectos do alumnado","texto":"Os microproxectos Eco-Étika presentados e dinamizados polo alumnado e o profesorado dos centros participantes.","imaxe":"f-stand-alumnas","imaxeAlt":"Alumnas explicando o seu stand"},{"titulo":"Investigacións de ciencia cidadá no rural","texto":"Os centros rurais vinculados a Postgrowth S.A.:Rural comparten as súas investigacións sobre a transición ecolóxica xusta.","imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando unha investigación"},{"titulo":"II Foro de Desenvolvemento Local","texto":"O rural ante a transición ecolóxica xusta: mesas de deliberación entre alumnado, profesorado e actores do territorio.","imaxe":"f-charla-auditorio","imaxeAlt":"Charla no salón de actos"},{"titulo":"I Conferencia COOPEDUGAL","texto":"Dúas xornadas de relatorios, experiencias e o espazo «O Local dende o Sur», vinculadas á Feira.","imaxe":"f-exposicion-carteis","imaxeAlt":"Exposición de carteis no corredor"},{"titulo":"Obradoiros, charlas-foro, xogos e escape rooms","texto":"Propostas de centros, entidades sociais, ONGD, universidade e iniciativas do territorio.","imaxe":"f-xogo-inclusivo","imaxeAlt":"Crianzas xogando a un xogo inclusivo"}]},{"id":"0elu1fbd","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen o fai posible","titulo":"Organiza, impulsan e apoian.","texto":"SENDA 2030 está financiado pola Xunta de Galicia a través da Cooperación Galega.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Co apoio de","entidades":["cooperacion-galega","cfr-pontevedra"]}]},{"id":"c5ugfyca","tipo":"noticias","oculta":false,"fondo":"branco","etiqueta":"Actualidade","titulo":"Noticias do camiño.","edicion":"2027","numero":6},{"id":"04eyx529","tipo":"chamada","oculta":false,"fondo":"morado","titulo":"Queres participar nesta edición?","texto":"Centros educativos, entidades, empresas e medios: escríbenos e contámosche como.","botons":[{"texto":"Participa","url":"/participa/","estilo":"principal"}]}]}', 973) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas', 'inicio', '{"seccions":[{"id":"swkfxb","tipo":"heroe","oculta":false,"fondo":"claro","etiqueta":"#AFeira · IES Luís Seoane · Pontevedra","titulo":"A Feira non son dous días.","destaque":"É un movemento.","texto":"Dende 2023, a Feira da Sostibilidade converte o IES Luís Seoane nun laboratorio aberto onde o alumnado investiga, actúa e constrúe cidadanía crítica xunto a centros educativos, universidade e entidades sociais.","imaxe":"f-multitude-corredor","imaxeAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira","cifras":[{"valor":"4","etiqueta":"edicións celebradas"},{"valor":"+1.000","etiqueta":"persoas participantes por edición"},{"valor":"30","etiqueta":"entidades colaboradoras na IV edición"},{"valor":"13","etiqueta":"centros de Galicia, España e Europa"}],"botons":[{"texto":"V Feira · 28–30 abril 2027","url":"/edicions/2027/","estilo":"principal"},{"texto":"Que é a Feira","url":"#a-feira","estilo":"secundario"}]},{"id":"sx40zj","tipo":"texto_imaxe","oculta":false,"fondo":"branco","ancla":"a-feira","etiqueta":"A Feira","titulo":"E se un instituto puidese cambiar o mundo?","corpo":"<p>A Feira da Sostibilidade «Pensa, consume e actúa» naceu da iniciativa do colectivo <strong>Eco-Étika</strong>, formado por alumnado do IES Luís Seoane de Pontevedra. O <strong>IES Luís Seoane</strong> organízaa, e <strong>CIDEL Galicia</strong> e o <strong>Post-Growth Innovation Lab da Universidade de Vigo</strong> impúlsana e apóiana.</p><p>O instituto, no barrio de Monte Porreiro, abre as súas portas cada primavera a centros educativos, universidade, entidades sociais, administracións e veciñanza. O alumnado non presenta só resultados: comparte o que investigou, dinamiza actividades e constrúe propostas para o seu territorio.</p>","imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando os resultados dunha investigación cidadá","posicion":"dereita","botons":[{"texto":"Coñece FeiraLab","url":"/feiralab/","estilo":"secundario"}]},{"id":"sy060z","tipo":"edicion_actual","oculta":false,"fondo":"claro","etiqueta":"Próxima edición"},{"id":"szqbsw","tipo":"tarxetas","oculta":false,"fondo":"verde","etiqueta":"FeiraLab","titulo":"Máis ca unha feira: un laboratorio.","texto":"Detrás da Feira hai un laboratorio de innovación educativa que traballa todo o curso con tres metodoloxías que se retroalimentan.","columnas":3,"items":[{"etiqueta":"ABP","titulo":"Investigar para comprender","texto":"O alumnado deseña e executa proxectos de investigación interdisciplinar sobre retos da Axenda 2030, conectando saberes científicos, sociais e artísticos.","url":"/feiralab/"},{"etiqueta":"ApS","titulo":"Actuar para transformar","texto":"O eixo que une aprendizaxe e acción comunitaria: o alumnado pon o seu coñecemento ao servizo da comunidade, con rede internacional con colectivos de Galicia e América Latina.","url":"/feiralab/"},{"etiqueta":"CC","titulo":"Investigar con rigor e impacto real","texto":"Co acompañamento científico da Universidade de Vigo, o alumnado convértese en investigador activo e conecta o local —o barrio de Monte Porreiro— co global.","url":"/feiralab/"}]},{"id":"s109jns","tipo":"edicions","oculta":false,"fondo":"claro","etiqueta":"As edicións","titulo":"Cada edición suma.","texto":"A Feira é un proceso vivo que medra cada curso: máis centros, máis entidades e máis proxectos do alumnado."},{"id":"s11yce4","tipo":"cita","oculta":false,"fondo":"verde","texto":"O futuro non se explica.","destaque":"Constrúese."},{"id":"s12ll8j","tipo":"noticias","oculta":false,"fondo":"branco","etiqueta":"Actualidade","titulo":"O proceso en directo.","numero":3},{"id":"s130zmn","tipo":"galeria","oculta":false,"fondo":"claro","etiqueta":"IV Feira da Sostibilidade","titulo":"Así foi a última Feira.","imaxes":[{"imaxe":"f-stand-2","alt":"Stand número 2 da Feira con materiais do alumnado"},{"imaxe":"f-stand-alumnas","alt":"Alumnas explicando o seu stand a outras visitantes"},{"imaxe":"f-xogo-inclusivo","alt":"Nenas e nenos xogando a un xogo inclusivo no chan"},{"imaxe":"f-stand-4-ruleta","alt":"Stand con ruleta de xogo e voluntariado atendendo"},{"imaxe":"f-exposicion-carteis","alt":"Exposición de carteis no corredor"},{"imaxe":"f-stand-15","alt":"Posto 15 do alumnado con produtos de deseño propio"},{"imaxe":"f-obradoiro-mans","alt":"Mans traballando nun obradoiro"},{"imaxe":"f-charla-auditorio","alt":"Charla no salón de actos ante o alumnado"}]},{"id":"s14zlbv","tipo":"logos","oculta":false,"fondo":"branco","etiqueta":"O ecosistema","titulo":"Unha rede que multiplica o impacto.","texto":"Entidades sociais, ONGD, cooperativas, administracións e iniciativas do territorio que fan a Feira posible.","grupos":[{"titulo":"Colaboran","entidades":["oxfam-intermon","adega","cogami","solidariedade-internacional","afectados-a57","ec4rural","cruz-vermella","feitoria-verde","galicia-ambiental","sig-comercio-xusto","casa-grande-de-xanceda","o-colmenar-de-sara","coxapo","aspanorcel","fundacion-balms","asociacion-boa-vida","aquelarre","ecoloxistas-en-accion","sembrando-bioxias"]}]},{"id":"s15jjlc","tipo":"chamada","oculta":false,"fondo":"morado","etiqueta":"Participa","titulo":"Non veñas só mirar. Participa.","texto":"Centros educativos, entidades, empresas e medios: hai moitas formas de formar parte da Feira.","botons":[{"texto":"Como participar","url":"/participa/","estilo":"principal"},{"texto":"@feiradasostibilidade","url":"https://www.instagram.com/feiradasostibilidade","estilo":"secundario"}]}]}', 0) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
